<?php require_once 'includes/bootstrap.php';$pageTitle='Sign in | Samay';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$username=trim($_POST['username']??'');$password=$_POST['password']??'';if($username===''||$password==='')$error='Enter your username and password.';else{try{$st=$conn->prepare('SELECT username,password FROM users WHERE username=? LIMIT 1');$st->bind_param('s',$username);$st->execute();$u=$st->get_result()->fetch_assoc();if($u&&password_verify($password,$u['password'])){session_regenerate_id(true);$_SESSION['user']=$u['username'];header('Location: account.php');exit;}else $error='Those details do not match an account. Please try again.';}catch(Throwable $e){$error='Account sign-in is not ready. Import database.sql and try again.';}}}require 'includes/header.php'; ?>
<section class="auth-shell"><div class="auth-art"><div class="kicker">Welcome back</div><h2>Your time.<br>Your story.</h2><p>Pick up where you left off.</p></div><form class="auth-form" method="post"><div class="kicker">Your Samay account</div><h1>Sign in.</h1><p>Good to see you again. Your saved timepieces are waiting.</p><?php if($error): ?><div class="form-error"><?=h($error)?></div><?php endif; ?><?php csrf_field(); ?><div class="form-field"><label for="username">Username</label><input id="username" name="username" autocomplete="username" required></div><div class="form-field"><label for="password">Password</label><input id="password" type="password" name="password" autocomplete="current-password" required></div><button class="button form-submit" type="submit">Sign in ↗</button><div class="form-note">New to Samay? <a href="register.php"><u>Create an account</u></a></div></form></section><?php require 'includes/footer.php'; ?>
